/**
 * Modules generated by build.mjs at bundle time (they do not exist on disk).
 */

/** Every `src/designs/*.ts`, found by listing the directory. `module` is the file's namespace; `error` a load or build failure. */
declare module "lab:designs" {
  export const designs: ReadonlyArray<{ readonly file: string; readonly module?: unknown; readonly error?: string }>
}

/** The app's colour tokens from `src/app/globals.css`, as sRGB 0..1 plus alpha, for both themes. */
declare module "lab:tokens" {
  type Tokens = { readonly [name: string]: readonly [number, number, number, number] }
  export const tokens: { readonly dark: Tokens; readonly light: Tokens }
}
